import fs7 from "fs-extra";
import path7 from "path";
import chalk5 from "chalk";
import ora4 from "ora";
import inquirer5 from "inquirer";
import { jsonrepair as jsonrepair3 } from "jsonrepair";
async function scanMdFiles(dir) {
  const results = [];
  if (!await fs7.pathExists(dir)) return results;
  const entries = await fs7.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path7.join(dir, entry.name);
    if (entry.isDirectory()) results.push(...await scanMdFiles(fullPath));
    else if (entry.isFile() && entry.name.endsWith(".md")) results.push(fullPath);
  }
  return results;
}
function extractLinks(content) {
  return [...content.matchAll(/\[\[([^\]|]+)(?:\|[^\]]+)?\]\]/g)].map((m) => m[1].trim());
}
async function lintCmd(config, options) {
  const wikiDir = path7.join(config.wikiRoot, config.paths.wiki);
  const indexPath = path7.join(wikiDir, "index.md");
  console.log(chalk5.bold.cyan("\n\u{1F50D} Running Wiki Lint...\n"));
  console.log(chalk5.bold("Phase 1: Static Analysis"));
  const allWikiFiles = await scanMdFiles(wikiDir);
  const pageFiles = allWikiFiles.filter((f) => !["index.md", "log.md"].includes(path7.basename(f)));
  const pageBasenames = new Set(pageFiles.map((f) => path7.basename(f, ".md")));
  const allLinkedNames = /* @__PURE__ */ new Set();
  for (const file of allWikiFiles) {
    const content = await fs7.readFile(file, "utf8");
    extractLinks(content).forEach((l) => allLinkedNames.add(l));
  }
  const orphans = [];
  for (const file of pageFiles) {
    const name = path7.basename(file, ".md");
    const isLinked = [...allLinkedNames].some((l) => l.toLowerCase().replace(/[^a-z0-9]/g, "") === name.toLowerCase().replace(/[^a-z0-9]/g, ""));
    if (!isLinked) orphans.push(name);
  }
  const deadLinks = [];
  for (const file of allWikiFiles) {
    const content = await fs7.readFile(file, "utf8");
    const links = extractLinks(content);
    for (const link of links) {
      const linkCanon = link.toLowerCase().replace(/[^a-z0-9]/g, "");
      const exists = [...pageBasenames].some((b) => b.toLowerCase().replace(/[^a-z0-9]/g, "") === linkCanon);
      if (!exists) deadLinks.push({ file: path7.relative(config.wikiRoot, file), link });
    }
  }
  const indexGaps = [];
  if (await fs7.pathExists(indexPath)) {
    const indexContent2 = await fs7.readFile(indexPath, "utf8");
    const indexLinked = new Set(extractLinks(indexContent2).map((l) => l.toLowerCase().replace(/[^a-z0-9]/g, "")));
    for (const file of pageFiles) {
      const name = path7.basename(file, ".md");
      if (!indexLinked.has(name.toLowerCase().replace(/[^a-z0-9]/g, ""))) {
        indexGaps.push(path7.relative(config.wikiRoot, file));
      }
    }
  }
  if (orphans.length === 0) {
    console.log(chalk5.green("  \u2713 No orphan pages found."));
  } else {
    console.log(chalk5.yellow(`  \u26A0 ${orphans.length} orphan page(s) (no incoming links):`));
    orphans.forEach((o) => console.log(`    - ${o}`));
  }
  if (deadLinks.length === 0) {
    console.log(chalk5.green("  \u2713 No dead links found."));
  } else {
    console.log(chalk5.red(`  \u2717 ${deadLinks.length} dead link(s) pointing to non-existent pages:`));
    deadLinks.forEach((d) => console.log(`    - [[${d.link}]] in ${d.file}`));
  }
  if (indexGaps.length === 0) {
    console.log(chalk5.green("  \u2713 All pages are indexed."));
  } else {
    console.log(chalk5.yellow(`  \u26A0 ${indexGaps.length} page(s) missing from index.md:`));
    indexGaps.forEach((g) => console.log(`    - ${g}`));
  }
  if (options.skipLlm) {
    console.log(chalk5.gray("\n(Skipping LLM analysis \u2014 --skip-llm flag set)\n"));
    return;
  }
  console.log(chalk5.bold("\nPhase 2: LLM Semantic Analysis"));
  const llm = new LLMClient(config);
  const pb = new PromptBuilder();
  const wm = new WikiManager(config);
  const indexContent = await wm.getIndexContent();
  const conceptDir = path7.join(wikiDir, "concepts");
  const conceptFiles = await scanMdFiles(conceptDir);
  const answersDir = path7.join(wikiDir, "answers");
  const answerFiles = await scanMdFiles(answersDir);
  const allPageContents = [];
  for (const file of [...conceptFiles, ...answerFiles]) {
    try {
      const content = await fs7.readFile(file, "utf8");
      allPageContents.push({ name: path7.basename(file, ".md"), content });
    } catch {
    }
  }
  const spinner = ora4("Asking LLM to analyze wiki for contradictions and gaps...").start();
  let report = null;
  try {
    const prompt = await pb.buildLintPrompt({ indexContent, pages: allPageContents });
    const response = await llm.chat([{ role: "user", content: prompt }]);
    spinner.stop();
    if (!response) throw new Error("Empty response from LLM");
    const jsonStart = response.indexOf("{");
    const jsonEnd = response.lastIndexOf("}");
    if (jsonStart === -1 || jsonEnd === -1) throw new Error("No JSON in LLM response");
    const rawJson = response.substring(jsonStart, jsonEnd + 1);
    try {
      report = JSON.parse(rawJson);
    } catch {
      report = JSON.parse(jsonrepair3(rawJson));
    }
  } catch (err) {
    spinner.fail("LLM analysis failed.");
    console.error(err);
    return;
  }
  if (report.contradictions?.length > 0) {
    console.log(chalk5.red(`
  \u2717 ${report.contradictions.length} potential contradiction(s):`));
    report.contradictions.forEach((c) => {
      console.log(chalk5.red(`    \u2022 [${c.pages.join(" vs ")}]`));
      console.log(chalk5.gray(`      ${c.description}`));
    });
  } else {
    console.log(chalk5.green("  \u2713 No semantic contradictions detected."));
  }
  if (report.missing_concepts?.length > 0) {
    console.log(chalk5.yellow(`
  \u26A0 ${report.missing_concepts.length} missing concept(s) suggested:`));
    report.missing_concepts.forEach((m) => {
      console.log(chalk5.yellow(`    \u2022 [[${m.name}]]`));
      console.log(chalk5.gray(`      ${m.rationale}`));
    });
  } else {
    console.log(chalk5.green("  \u2713 No missing concepts detected."));
  }
  if (report.shallow_pages?.length > 0) {
    console.log(chalk5.yellow(`
  \u26A0 ${report.shallow_pages.length} shallow/placeholder page(s):`));
    report.shallow_pages.forEach((s) => {
      console.log(chalk5.yellow(`    \u2022 ${s.name}: ${s.reason}`));
    });
  } else {
    console.log(chalk5.green("  \u2713 All pages appear to have substantial content."));
  }
  if (report.index_gaps?.length > 0) {
    const llmGaps = [.../* @__PURE__ */ new Set([...(report.index_gaps || []).map((g) => g.file), ...indexGaps])];
    console.log(chalk5.yellow(`
  \u26A0 Index gap suggestions from LLM:`));
    report.index_gaps.forEach((g) => {
      console.log(chalk5.yellow(`    \u2022 ${g.file}`));
      console.log(chalk5.gray(`      ${g.suggestion}`));
    });
  }
  console.log("");
  const hasFixes = orphans.length > 0 || report.missing_concepts?.length > 0 || indexGaps.length > 0;
  if (!hasFixes) {
    console.log(chalk5.green("\u{1F389} Wiki is healthy! Nothing to fix.\n"));
    return;
  }
  let shouldFix = options.fix;
  if (!shouldFix) {
    const confirm = await inquirer5.prompt([{
      type: "confirm",
      name: "apply",
      message: "Do you want the LLM to generate and apply fix proposals for the above issues?",
      default: false
    }]);
    shouldFix = confirm.apply;
  }
  if (!shouldFix) {
    console.log(chalk5.gray("No fixes applied. Run with --fix to auto-apply.\n"));
    return;
  }
  const fixOperations = [];
  const newConceptEntries = [];
  for (const mc of report.missing_concepts || []) {
    const safeName = mc.name.toLowerCase().replace(/[/\\|]/g, "-").replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "").replace(/-+/g, "-");
    const stubPath = `wiki/concepts/${safeName}.md`;
    const exists = await fs7.pathExists(path7.join(config.wikiRoot, stubPath));
    if (!exists) {
      fixOperations.push({
        type: "create",
        path: stubPath,
        content: `# ${mc.name}

> [!NOTE]
> This page was auto-created by \`wiki lint\`. It needs to be filled in.

${mc.rationale}
`
      });
      newConceptEntries.push({ safeName, displayName: mc.name });
    }
  }
  const answerOrphans = orphans.filter((o) => indexGaps.some((g) => g.includes(o)));
  if (newConceptEntries.length > 0 || answerOrphans.length > 0) {
    let currentIndex = indexContent;
    if (newConceptEntries.length > 0) {
      const newConceptLines = newConceptEntries.map((e) => `* [[${e.safeName}|${e.displayName}]] - *(auto-created stub, needs content)*`).join("\n");
      if (currentIndex.includes("## Concepts")) {
        currentIndex = currentIndex.replace(
          /## Concepts\n([\s\S]*?)(\n## |\n$|$)/,
          (match, body, tail) => `## Concepts
${body.trimEnd()}
${newConceptLines}
${tail}`
        );
      } else {
        currentIndex += `

## Concepts
${newConceptLines}
`;
      }
    }
    if (answerOrphans.length > 0) {
      const newAnswerLines = answerOrphans.map((o) => `* [[${o}]]`).join("\n");
      if (currentIndex.includes("## Answers")) {
        currentIndex = currentIndex.replace(
          /## Answers\n([\s\S]*?)(\n## |\n$|$)/,
          (match, body, tail) => `## Answers
${body.trimEnd()}
${newAnswerLines}
${tail}`
        );
      } else {
        currentIndex += `

## Answers
${newAnswerLines}
`;
      }
    }
    fixOperations.push({
      type: "update",
      path: "wiki/index.md",
      content: currentIndex
    });
  }
  if (fixOperations.length === 0) {
    console.log(chalk5.gray("\nNo automatic fixes could be generated. Review issues manually.\n"));
    return;
  }
  console.log(chalk5.cyan("\nProposed fix operations:"));
  fixOperations.forEach((op) => {
    console.log(`  ${chalk5.green(`[${op.type.toUpperCase()}]`)} ${op.path}`);
  });
  const confirm2 = await inquirer5.prompt([{
    type: "confirm",
    name: "apply",
    message: "Apply these fix operations?",
    default: true
  }]);
  if (confirm2.apply) {
    await wm.executeOperations(fixOperations);
    await wm.appendLog("lint", `Applied ${fixOperations.length} fix(es).`);
    console.log(chalk5.green(`
\u2714 Applied ${fixOperations.length} fix(es).
`));
  } else {
    console.log(chalk5.gray("Changes discarded.\n"));
  }
}

// src/commands/list.ts
import fs8 from "fs-extra";
import path8 from "path";
import chalk6 from "chalk";
async function scanMdFiles2(dir) {
  const results = [];
  if (!await fs8.pathExists(dir)) return results;
  const entries = await fs8.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path8.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...await scanMdFiles2(fullPath));
    } else if (entry.isFile() && entry.name.endsWith(".md")) {
      results.push(fullPath);
    }
  }
  return results;
}
function canonicalize(name) {
  return name.toLowerCase().replace(/[^a-z0-9\u4e00-\u9fa5]/g, "");
}
async function listCmd(config, type, target, options) {
  const wikiDir = path8.join(config.wikiRoot, config.paths.wiki);
  const rawUntrackedDir = path8.join(config.wikiRoot, config.paths.raw, "untracked");
  const rawIngestedDir = path8.join(config.wikiRoot, config.paths.raw, "ingested");
  switch (type.toLowerCase()) {
    case "raw": {
      console.log(chalk6.bold.cyan("\n--- Raw Sources ---"));
      const untracked = await scanMdFiles2(rawUntrackedDir);
      console.log(chalk6.yellow(`
Pending / Untracked (${untracked.length}):`));
      untracked.forEach((f) => console.log(`  - ${path8.relative(config.wikiRoot, f)}`));
      const ingested = await scanMdFiles2(rawIngestedDir);
      console.log(chalk6.green(`
Ingested (${ingested.length}):`));
      ingested.forEach((f) => console.log(`  - ${path8.relative(config.wikiRoot, f)}`));
      console.log("");
      break;
    }
    case "pages": {
      console.log(chalk6.bold.cyan("\n--- Wiki Pages ---"));
      const allWikiFiles = await scanMdFiles2(wikiDir);
      const filtered = allWikiFiles.filter((f) => !["index.md", "log.md"].includes(path8.basename(f)));
      filtered.forEach((f) => {
        const name = path8.basename(f, ".md");
        console.log(`  \u{1F4C4} ${chalk6.green(name)} ${chalk6.gray(`(${path8.relative(config.wikiRoot, f)})`)}`);
      });
      console.log(chalk6.gray(`
Total: ${filtered.length} pages
`));
      break;
    }
    case "orphans": {
      console.log(chalk6.bold.cyan("\n--- Orphan Pages ---"));
      const allWikiFiles = await scanMdFiles2(wikiDir);
      const pageFiles = allWikiFiles.filter((f) => !["index.md", "log.md"].includes(path8.basename(f)));
      const pageInfo = pageFiles.map((f) => {
        const name = path8.basename(f, ".md");
        return { name, canon: canonicalize(name) };
      });
      const orphans = new Set(pageInfo.map((i) => i.name));
      const allContentFiles = [path8.join(wikiDir, "index.md"), ...pageFiles];
      for (const file of allContentFiles) {
        if (!await fs8.pathExists(file)) continue;
        const content = await fs8.readFile(file, "utf8");
        const matches = [...content.matchAll(/\[\[(.*?)\]\]/g)];
        for (const match of matches) {
          const linkedCanon = canonicalize(match[1]);
          const pInfo = pageInfo.find((i) => i.canon === linkedCanon || linkedCanon.includes(i.canon));
          if (pInfo) {
            orphans.delete(pInfo.name);
          }
        }
      }
      if (orphans.size === 0) {
        console.log(chalk6.green("\nNo orphan pages found! Every page is linked. \u{1F389}\n"));
      } else {
        console.log(chalk6.yellow(`
Found ${orphans.size} orphan pages (no incoming links):
`));
        Array.from(orphans).forEach((name) => console.log(`  - ${name}`));
        console.log(chalk6.gray(`
Tip: You can use 'wiki lint' to have the LLM automatically restructure or connect them.
`));
      }
      break;
    }
    case "backlinks": {
      if (!target) {
        console.log(chalk6.red('Please provide a target page name. Usage: wiki list backlinks "Page Name"'));
        return;
      }
      console.log(chalk6.bold.cyan(`
--- Backlinks for "[[${target}]]" ---`));
      const targetCanon = canonicalize(target);
      const allWikiFiles = await scanMdFiles2(wikiDir);
      let found = 0;
      for (const file of allWikiFiles) {
        if (!await fs8.pathExists(file)) continue;
        const content = await fs8.readFile(file, "utf8");
        const matches = [...content.matchAll(/\[\[(.*?)\]\]/g)];
        const hasLink = matches.some((match) => {
          const linkedCanon = canonicalize(match[1]);
          return linkedCanon === targetCanon || linkedCanon.includes(targetCanon);
        });
        if (hasLink) {
          console.log(`  \u{1F517} ${chalk6.green(path8.basename(file, ".md"))}`);
          found++;
        }
      }
      if (found === 0) {
        console.log(chalk6.gray(`
No pages link to "[[${target}]]".
`));
      } else {
        console.log(chalk6.gray(`
Total: ${found} referring pages
`));
      }
      break;
    }
    default:
      console.log(chalk6.red(`
Unknown list type: ${type}`));
      console.log(`Supported types: raw, pages, orphans, backlinks
`);
  }
}

// bin/wiki.ts
var program = new Command();
async function main() {
  const config = await loadConfig();
  program.name("wiki").description("LLM Wiki CLI").version("0.1.3");
  program.command("init").description("Initialize a new LLM wiki repository").option("-f, --force", "Force overwrite existing directories").action((options) => initCmd(config, options));
  program.command("raw").description("Add a raw source document interactively").option("--content <text>", "Direct content input").option("--source <string>", "Source description").option("--type <type>", "Type of raw source").option("--no-editor", "Use terminal to paste directly").action((options) => rawCmd(config, options));
  program.command("ingest").description("Ingest raw documents into the wiki").argument("[file]", "Specific file to ingest").option("--all", "Ingest all pending files").option("-y, --yes", "Skip confirmation").option("--dry-run", "Show logic plan without writing").option("-d, --debug", "Print debug payload sent to LLM").action((file, options) => ingestCmd(config, file, options));
  program.command("query").description("Query the wiki via the LLM").argument("[question]", "The question").option("--save", "Save answer without asking").option("--page <name>", "Name of the saved page").option("--no-save", "Do not save answer").option("-d, --debug", "Print debug context info (e.g., accessed pages)").action((question, options) => queryCmd(config, question, options));
  program.command("lint").description("Analyze the wiki for inconsistencies or orphans").option("--fix", "Automatically apply simple fixes").option("--skip-llm", "Only run static analysis, skip LLM call").action((options) => lintCmd(config, options));
  program.command("list").description("List wiki items").argument("[type]", "raw / pages / orphans / backlinks", "pages").argument("[target]", "Target page for backlinks (optional)", "").action((type, target, options) => listCmd(config, type, target, options));
  program.parseAsync(process.argv);
}
main().catch((err) => {
  console.error(err);
  process.exit(1);
});
